def test_cancels_composition_when_robot_enters_disabled(scheduler, events, robot):
    mech = DummyMechanism("mech", scheduler)
    child = mech.run(Coroutine.park).named("Child")

    def body(co: Coroutine):
        yield from co.await_(child)

    parent = Command.no_requirements(body).named("Parent")
    scheduler.schedule(parent)
    scheduler.run()
    assert scheduler.get_running_commands() == [parent, child]
    robot.enabled = False
    scheduler.run()
    assert scheduler.get_running_commands() == []
    assert_event(events, Canceled, lambda e: e.command is parent)
    assert_event(events, Canceled, lambda e: e.command is child)


