def test_cancels_composition_when_child_cannot_be_scheduled(scheduler, events, robot):
    mech = DummyMechanism("mech", scheduler)
    child = mech.run(Coroutine.park).named("Command")

    def body(co: Coroutine):
        yield from co.wait_until(lambda: not robot.enabled)
        yield from co.await_(child)

    parent = Command.no_requirements(body).named("Parent Command")
    scheduler.schedule(parent)
    scheduler.run()
    assert scheduler.get_running_commands() == [parent]
    robot.enabled = False
    scheduler.run()
    assert scheduler.get_running_commands() == []
    assert_event(events, ForkFailure,
                 lambda e: e.command is parent and len(e.failures) == 1
                 and isinstance(e.failures[0], RequiresUnsafeMechanisms)
                 and e.failures[0].command is child
                 and e.failures[0].unsafe_mechanisms == {mech})
    assert_event(events, Canceled, lambda e: e.command is parent)


